class ZeroEvenOdd {
  private final int n;
  private int state = 0; // 0: zero, 1: odd, 2: even

  public ZeroEvenOdd(int n) {
    this.n = n;
  }

  public synchronized void zero(java.util.function.IntConsumer printNumber)
      throws InterruptedException {
    for (int i = 1; i <= n; i++) {
      while (state != 0) wait();
      printNumber.accept(0);
      state = (i & 1) == 1 ? 1 : 2;
      notifyAll();
    }
  }

  public synchronized void even(java.util.function.IntConsumer printNumber)
      throws InterruptedException {
    for (int i = 2; i <= n; i += 2) {
      while (state != 2) wait();
      printNumber.accept(i);
      state = 0;
      notifyAll();
    }
  }

  public synchronized void odd(java.util.function.IntConsumer printNumber)
      throws InterruptedException {
    for (int i = 1; i <= n; i += 2) {
      while (state != 1) wait();
      printNumber.accept(i);
      state = 0;
      notifyAll();
    }
  }
}
